t.script:

// Load dashboard data
document.addEventListener('DOMContentLoaded', function() {
    initializeFilters();
    loadDashboardData();

    // Add event listener for Apply button
    document.getElementById('apply-filters').addEventListener('click', function() {
        loadDashboardData();
    });
});

function initializeFilters() {
    // Populate year dropdown (2025 to 2025 + 50 years)
    const yearSelect = document.getElementById('year-select');
    const currentYear = new Date().getFullYear();
    const currentMonth = new Date().getMonth() + 1;
    const startYear = 2025;
    const endYear = 2025 + 50; // 2075

    for (let year = startYear; year <= endYear; year++) {
        const option = document.createElement('option');
        option.value = year;
        option.textContent = year;
        if (year === currentYear || (currentYear < startYear && year === startYear)) {
            option.selected = true;
        }
        yearSelect.appendChild(option);
    }

    // Set current month as selected
    document.getElementById('month-select').value = currentMonth;
}

async function loadDashboardData() {
    const year = document.getElementById('year-select').value;
    const month = document.getElementById('month-select').value;

    try {
        const response = await fetch('/helpdesk/dashboard/data', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'X-Requested-With': 'XMLHttpRequest'
            },
            body: JSON.stringify({
                jsonrpc: '2.0',
                method: 'call',
                params: {
                    year: parseInt(year),
                    month: parseInt(month)
                }
            })
        });

        const result = await response.json();
        const data = result.result;

        renderDashboard(data);
        updateSubtitle(data);

    } catch (error) {
        console.error('Error loading dashboard:', error);
        document.getElementById('dashboard-tbody').innerHTML = 
            '<tr><td colspan="7" class="text-center text-danger py-4">' +
            '<i class="fa fa-exclamation-triangle mr-2"></i>Error loading data</td></tr>';
    }
}

function renderDashboard(data) {
    const tbody = document.getElementById('dashboard-tbody');
    let html = '';

    if (data.rows && data.rows.length > 0) {
        // Calculate week totals
        const weekTotals = [0, 0, 0, 0];
        let grandTotal = 0;

        // Render rows
        data.rows.forEach((row, index) => {
            html += '<tr>';
            html += '<td class="text-center font-weight-bold">' + (index + 1) + '</td>';
            html += '<td>' + (row.tag || 'Unknown') + '</td>';
            html += '<td class="text-center">' + (row.week_counts[0] || 0) + '</td>';
            html += '<td class="text-center">' + (row.week_counts[1] || 0) + '</td>';
            html += '<td class="text-center">' + (row.week_counts[2] || 0) + '</td>';
            html += '<td class="text-center">' + (row.week_counts[3] || 0) + '</td>';
            html += '<td class="text-center font-weight-bold">' + (row.total || 0) + '</td>';
            html += '</tr>';

            // Calculate totals
            row.week_counts.forEach((count, weekIndex) => {
                weekTotals[weekIndex] += count || 0;
                grandTotal += count || 0;
            });
        });

        // Add total row
        html += '<tr class="bg-light font-weight-bold">';
        html += '<td class="text-center">' + (data.rows.length + 1) + '</td>';
        html += '<td>Total</td>';
        html += '<td class="text-center">' + weekTotals[0] + '</td>';
        html += '<td class="text-center">' + weekTotals[1] + '</td>';
        html += '<td class="text-center">' + weekTotals[2] + '</td>';
        html += '<td class="text-center">' + weekTotals[3] + '</td>';
        html += '<td class="text-center">' + grandTotal + '</td>';
        html += '</tr>';

    } else {
        const monthName = data.month_name || 'Selected Period';
        const year = data.selected_year || '';
        html = '<tr><td colspan="7" class="text-center text-muted py-4">' +
               '<i class="fa fa-info-circle mr-2"></i>No complaint data found for ' + monthName + ' ' + year + '</td></tr>';
    }

    tbody.innerHTML = html;
    document.getElementById('last-updated').textContent = new Date().toLocaleString();
}

function updateSubtitle(data) {
    const monthName = data.month_name || 'Unknown Month';
    const year = data.selected_year || 'Unknown Year';
    const companyName = data.company_name || 'Company';
    document.getElementById('dashboard-subtitle').textContent = monthName + ' ' + year + ' ' + companyName;
}
